The notes implement $c=\bar a b+a\bar b$ with two inverters, two AND gates and an OR gate. This dataflow version keeps the internal gate signals and requires no additional component files.

```vhdl
entity xor2 is
    port (a, b : in bit; c : out bit);
end entity xor2;

architecture exm1 of xor2 is
    signal p, q, r, s : bit;
begin
    p <= not a;
    q <= not b;
    r <= p and b;
    s <= a and q;
    c <= r or s;
end architecture exm1;

entity tb_xor2 is
end entity tb_xor2;

architecture io of tb_xor2 is
    signal u, v, w : bit;
begin
    dut: entity work.xor2(exm1) port map (a => u, b => v, c => w);
    u <= '0', '1' after 100 ns, '0' after 200 ns;
    v <= '0', '1' after 150 ns, '0' after 300 ns, '1' after 420 ns;

    check: process
    begin
        wait for 1 ns;
        assert w = '0' severity failure;
        wait for 100 ns;
        assert w = '1' severity failure;
        wait for 50 ns;
        assert w = '0' severity failure;
        wait for 50 ns;
        assert w = '1' severity failure;
        wait for 100 ns;
        assert w = '0' severity failure;
        wait for 120 ns;
        assert w = '1' severity failure;
        wait;
    end process;
end architecture io;
```

